return {["fb200_01"]={["down"]=[[fb200_02]],["dsc"]=[[这是一间避暑小屋，这里翠竹环绕，鸟语花香，屋顶虽是茅草搭就，却将阳光遮了个严严实实。坐在其中，凉风习习，十分舒服。]],["id"]=[[fb200_01]],["item1"]=[[fb200item13]],["item2"]=[[fb200item22]],["name"]=[[避暑小屋]],["permission"]=1,["stepMusic"]=[[mudiban]],["up"]=[[fb200_19]]},["fb200_02"]={["dsc"]=[[这间小屋藏在竹林中，屋体由慈竹搭就，推门进入屋子，一股淡淡的竹子清香味在四周晕开。]],["id"]=[[fb200_02]],["item1"]=[[fb200item18]],["item2"]=[[fb200item29]],["item3"]=[[fb200item30]],["name"]=[[竹林小屋]],["permission"]=1,["right"]=[[fb200_03]],["stepMusic"]=[[mudiban]],["up"]=[[fb200_01]]},["fb200_03"]={["dsc"]=[[这是一个坐北朝南，窗明几净的房间，房中的桌椅和书柜整整齐齐。]],["id"]=[[fb200_03]],["item1"]=[[fb200item1]],["item2"]=[[fb200item2]],["item3"]=[[fb200item3]],["left"]=[[fb200_02]],["name"]=[[工作室]],["permission"]=1,["right"]=[[fb200_04]],["stepMusic"]=[[mudiban]]},["fb200_04"]={["down"]=[[fb200_09]],["dsc"]=[[这里是大厅，宽敞明亮的房间，四周摆着几盆你叫不上名的植物，墙上挂着一幅巨大的卷轴，上面用行书写着“小猴跳跳”四个大字，飘逸灵动。]],["id"]=[[fb200_04]],["item1"]=[[fb200item17]],["left"]=[[fb200_03]],["name"]=[[大厅]],["permission"]=1,["right"]=[[fb200_05]],["stepMusic"]=[[mudiban]]},["fb200_05"]={["dsc"]=[[此处是宽敞的走廊，地面被擦得一尘不染，一低头便可看见自己的倒影。]],["id"]=[[fb200_05]],["item1"]=[[fb200item16]],["left"]=[[fb200_04]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb200_06]],["stepMusic"]=[[mudiban]]},["fb200_06"]={["dsc"]=[[一阵墨香味裹挟着小炉熏香味向你席来，这里便是书房了。书架一排排陈列开来，书卷被分门别类地整齐放好，东南角摆着一张楠木桌与两把椅子，桌上一本书打开放着，旁边的茶盏还往外冒着氤氲热气。]],["id"]=[[fb200_06]],["item1"]=[[fb200item4]],["item2"]=[[fb200item10]],["left"]=[[fb200_05]],["name"]=[[书房]],["permission"]=1,["stepMusic"]=[[mudiban]]},["fb200_07"]={["dsc"]=[[一进入房间，就让人眼前一亮，四周散放着各种玩物，桌上各类小吃果脯堆积成山。你随意拿起一样玩物，上面写着“三国杀”。]],["id"]=[[fb200_07]],["item1"]=[[fb200item12]],["name"]=[[休息室]],["permission"]=1,["right"]=[[fb200_08]],["stepMusic"]=[[mudiban]]},["fb200_08"]={["down"]=[[fb200_12]],["dsc"]=[[这里门口摆放着绘着四君子的屏风，绕过屏风，跳跃的炉火映照出整个房间的轮廓，从入口处一路铺开松软的牦牛毯，一脚上去浅浅一印，十分舒服。]],["id"]=[[fb200_08]],["item1"]=[[fb200item9]],["left"]=[[fb200_07]],["name"]=[[会客厅]],["permission"]=1,["stepMusic"]=[[mudiban]]},["fb200_09"]={["down"]=[[fb200_14]],["dsc"]=[[这里是回廊，廊角是一处画柱，上面刻着凤舞于天的浮雕，栩栩如生，呼之欲出。]],["id"]=[[fb200_09]],["item1"]=[[fb200item27]],["name"]=[[回廊]],["permission"]=1,["stepMusic"]=[[mudiban]],["up"]=[[fb200_04]]},["fb200_10"]={["down"]=[[fb200_15]],["dsc"]=[[此处是宽敞的走廊，地面被擦得一尘不染，一低头便可看见自己的倒影。]],["id"]=[[fb200_10]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb200_11]],["stepMusic"]=[[mudiban]]},["fb200_11"]={["dsc"]=[[人未至味先至，这里便是茅房了。]],["id"]=[[fb200_11]],["left"]=[[fb200_10]],["name"]=[[茅房]],["permission"]=1,["stepMusic"]=[[mudiban]]},["fb200_12"]={["dsc"]=[[一阵墨香味裹挟着小炉熏香味向你席来，这里便是书房了。书架一排排陈列开来，书卷被分门别类地整齐放好，东南角摆着一张楠木桌与两把椅子，桌上一本书打开放着，旁边的茶盏还往外冒着氤氲热气。]],["id"]=[[fb200_12]],["item1"]=[[fb200item5]],["item2"]=[[fb200item6]],["item3"]=[[fb200item7]],["name"]=[[书房]],["permission"]=1,["right"]=[[fb200_13]],["stepMusic"]=[[mudiban]],["up"]=[[fb200_08]]},["fb200_13"]={["dsc"]=[[这是一个坐北朝南，窗明几净的房间，房中的桌椅和书柜整整齐齐。]],["id"]=[[fb200_13]],["item1"]=[[fb200item8]],["item2"]=[[fb200item25]],["left"]=[[fb200_12]],["name"]=[[工作室]],["permission"]=1,["right"]=[[fb200_14]],["stepMusic"]=[[mudiban]]},["fb200_14"]={["down"]=[[fb200_16]],["dsc"]=[[这里是回廊，廊角是一处画柱，上面刻着凤舞于天的浮雕，栩栩如生，呼之欲出。]],["id"]=[[fb200_14]],["item1"]=[[fb200item28]],["left"]=[[fb200_13]],["name"]=[[回廊]],["permission"]=1,["right"]=[[fb200_15]],["stepMusic"]=[[mudiban]],["up"]=[[fb200_09]]},["fb200_15"]={["down"]=[[fb200_17]],["dsc"]=[[这里是餐厅，南北风味，天下奇珍均汇聚于此，各类菜肴被一字排开，随手可取。]],["id"]=[[fb200_15]],["item1"]=[[fb200item11]],["left"]=[[fb200_14]],["name"]=[[餐厅]],["permission"]=1,["stepMusic"]=[[mudiban]],["up"]=[[fb200_10]]},["fb200_16"]={["down"]=[[fb200_18]],["dsc"]=[[此处是议事厅，只简单地摆着一张红木圆桌、几把椅子。]],["id"]=[[fb200_16]],["item1"]=[[fb200item24]],["item2"]=[[fb200item24]],["name"]=[[议事厅]],["permission"]=1,["stepMusic"]=[[mudiban]],["up"]=[[fb200_14]]},["fb200_17"]={["dsc"]=[[这里门口摆放着绘着四君子的屏风，绕过屏风，跳跃的炉火映照出整个房间的轮廓，从入口处一路铺开松软的牦牛毯，一脚上去浅浅一印，十分舒服。]],["id"]=[[fb200_17]],["item1"]=[[fb200item26]],["name"]=[[会客厅]],["permission"]=1,["stepMusic"]=[[mudiban]]